import json, os, subprocess, sys, time

S = "/Users/kevingalligan/devel/framejob-codecs/tools/proof/work/codec-spike"
SVT = f"{S}/src/svt-av1/Bin/Release/SvtAv1EncApp"
OUT = f"{S}/out-crf"
LOG = f"{S}/crf.jsonl"
FRAMES = 150
CLIPS = {"gh5": 25, "promo": 30, "real8": 30}
# Bits per pixel per frame at 1920 × 1080 × 30 of the sheet's tiers (rounded to 100 kbps,
# ExportSheetOptions.QualityTier with AV1's 0.6) and "Format default" (0.07).
RATES = {"low": 2_400_000, "medium": 3_600_000, "default": 4_354_560, "high": 4_800_000,
         "maximum": 7_200_000}
BPP = {k: v / (1920 * 1080 * 30) for k, v in RATES.items()}
PRESETS = (8, 6, 4)
CRFS = range(18, 47, 2)


def rate(clip, tier):
    return round(BPP[tier] * 1920 * 1080 * CLIPS[clip])


def vmaf(dist, ref, tag):
    log = f"{OUT}/{tag}.vmaf.json"
    lavfi = ("[0:v]format=yuv420p,setpts=PTS-STARTPTS[d];[1:v]format=yuv420p,setpts=PTS-STARTPTS[r];"
             f"[d][r]libvmaf=log_fmt=json:log_path={log}:n_threads=12:"
             "feature=name=psnr|name=float_ssim")
    subprocess.run(["ffmpeg", "-hide_banner", "-loglevel", "error", "-i", dist, "-i", ref,
                    "-lavfi", lavfi, "-f", "null", "-"], check=True)
    pooled = json.load(open(log))["pooled_metrics"]
    return {"vmaf": round(pooled["vmaf"]["mean"], 3), "vmaf_min": round(pooled["vmaf"]["min"], 2),
            "psnr_y": round(pooled["psnr_y"]["mean"], 3),
            "float_ssim": round(pooled["float_ssim"]["mean"], 5)}


def encode(row, c, out, src, fps):
