    out = f"{OUT}/{tag}.ivf"
    c = [SVT, "-i", src, "-b", out, "--preset", str(preset), "--rc", "0", "--crf", str(crf),
         "--keyint", str(round(2 * fps)), "--irefresh-type", "2", "--progress", "0"]
    if cap_bps:
        c += ["--mbr", str(round(cap_bps / 1000))]
    encode({"kind": "svt", "clip": clip, "preset": preset, "crf": crf, "cap_bps": cap_bps,
            "tier": tier}, c, out, src, fps)


def rows():
    return [json.loads(line) for line in open(LOG)] if os.path.exists(LOG) else []


def table():
    got = rows()
    target = {(r["clip"], r["tier"]): r["vmaf"] for r in got if r["kind"] == "hevc"}
    sweep = [r for r in got if r["kind"] == "svt" and not r["cap_bps"]]
    print("HEVC VMAF at each rate: " + "; ".join(
        f"{c}/{t} {v}" for (c, t), v in sorted(target.items())))
    for preset in PRESETS:
        for tier in RATES:
            best = None
            for crf in sorted({r["crf"] for r in sweep if r["preset"] == preset}):
                at = {r["clip"]: r["vmaf"] for r in sweep if r["preset"] == preset and r["crf"] == crf}
                if len(at) == len(CLIPS) and all(at[c] >= target[(c, tier)] for c in CLIPS):
                    best = crf
            print(f"preset {preset} {tier} ({BPP[tier]:.4f} bpp): highest swept CRF meeting HEVC "
                  f"on every clip {best}")


def main():
    os.makedirs(OUT, exist_ok=True)
    what = sys.argv[1]
    if what == "hevc":
        hevc()
    elif what == "sweep":
        for preset in PRESETS:
            for crf in CRFS:
                for clip in CLIPS:
                    svt(clip, preset, crf)
    elif what == "verify":
        for spec in sys.argv[2:]:
            preset, tier, crf = spec.split(":")
            for clip in CLIPS:
                svt(clip, int(preset), int(crf), rate(clip, tier), tier)
    elif what == "table":
        table()


if __name__ == "__main__":
    main()

